 significance: 'अंबर का व्यापक सत्ता-राजनीति में प्रवेश; उत्तर भारत की बदलती शक्ति-संरचना में कछवाहा भूमिका',
 casualties: 'न्यूनतम; खुला युद्ध नहीं, नियंत्रित सैन्य सेवा',
