  fullStory: `अरावली की गोद में जब बादल गरजते थे, तो लगता था मानो स्वयं मेवाड़ की आत्मा अपनी प्रतिज्ञा दोहरा रही हो। उन्हीं प्रतिज्ञाओं के बीच 1540 ईस्वी में सिसोदिया वंश के महलों में एक शिशु ने जन्म लिया—वह था उदय सिंह द्वितीय। उस क्षण किसी को आभास न था कि यह बालक आगे चलकर न केवल मेवाड़ का रक्षक बनेगा, बल्कि एक ऐसे योद्धा का पिता भी होगा, जिसकी गर्जना सदियों तक गूँजेगी—महाराणा प्रताप।

जन्म के साथ ही उसके चारों ओर तलवारों की छाया थी। सिसोदिया वंश का इतिहास रक्त और अग्नि में लिखा गया था। महल के गलियारों में षड्यंत्र की धीमी फुसफुसाहटें, बुर्जों पर चौकसी, और सभा कक्षों में राजनीतिक तनाव—यह सब उसकी परवरिश का हिस्सा था। बालक उदय सिंह ने शैशव से ही समझ लिया कि राजपुत्र होना केवल वैभव नहीं, एक निरंतर युद्ध है।

उसका बचपन सुरक्षित नहीं था। मेवाड़ के भीतर सत्ता संघर्ष, बाहरी शत्रुओं की दृष्टि, और मुग़ल विस्तार की छाया—इन सबने उसकी आँखों में समय से पहले परिपक्वता भर दी। उसे अस्तबलों में भेजा गया, जहाँ घोड़ों की टापों के बीच संतुलन सीखा। धनुष की प्रत्यंचा उसकी उँगलियों में तनी, तलवार की धार उसकी भुजाओं में उतर गई। गुरु उसे सिखाते—“राजकुमार, शत्रु की चाल से पहले उसके इरादे को पहचानो।”

उस समय उत्तर भारत में एक नई शक्ति उभर रही थी। दिल्ली की गद्दी पर बैठा था एक महत्वाकांक्षी सम्राट—अकबर। उसका लक्ष्य केवल विजय नहीं, अधीनता था। कई राजपूत रियासतें संधि के मार्ग पर चली गईं, पर मेवाड़—वह अपनी स्वतंत्रता की शपथ पर अडिग था।

युवा होते-होते उदय सिंह ने समझ लिया कि मेवाड़ को केवल तलवार नहीं, रणनीति भी चाहिए। उसने सेना को पुनर्गठित करना आरंभ किया। पहाड़ी युद्धकला पर बल दिया गया। छोटी, तेज़ टुकड़ियाँ बनाई गईं जो अरावली की संकरी घाटियों में शत्रु को उलझा सकें। दुर्गों की मरम्मत हुई, रसद भंडार सुदृढ़ किए गए।

पहला बड़ा संघर्ष सीमांत क्षेत्र में हुआ, जहाँ मुग़ल टुकड़ी ने आगे बढ़कर एक छोटे दुर्ग पर अधिकार जमाने की कोशिश की। मैदान समतल था, पर पश्चिम में पहाड़ियों की शृंखला। उदय सिंह ने सेना को दो भागों में बाँटा। सामने से हल्का प्रतिरोध, और पहाड़ियों के पीछे से घात।

जैसे ही मुग़ल सेना आगे बढ़ी, मेवाड़ी अग्रिम पंक्ति पीछे हटती प्रतीत हुई। शत्रु ने इसे कमजोरी समझा। वे भीतर तक घुस आए। तभी पहाड़ियों से बाणों और गोलियों की वर्षा हुई। घोड़ों में भगदड़ मच गई। उदय सिंह ने तलवार उठाई—“अब!”

घुड़सवार टूट पड़े। तलवारें भिड़ीं। धूल और रक्त का मिश्रण हवा में भर गया। एक मुग़ल सूबेदार ने उदय सिंह को ललकारा। दोनों आमने-सामने। तलवारें टकराईं, ढालें काँपीं। अंततः उदय सिंह का वार सटीक पड़ा—सूबेदार धरती पर गिरा। शत्रु पीछे हट गया। यह विजय छोटी थी, पर संदेश स्पष्ट—मेवाड़ जीवित है।

पर असली परीक्षा तब आई जब चित्तौड़ की ओर मुग़ल सेना ने दृष्टि डाली। विशाल तोपें, अनगिनत सैनिक, और दीर्घ घेराबंदी की तैयारी। उदय सिंह ने स्थिति का आकलन किया। चित्तौड़ प्रतीक था, पर उसे समझ था कि दीर्घकालिक संघर्ष के लिए नेतृत्व का सुरक्षित रहना आवश्यक है।

सभा में तनाव था। कुछ सरदारों ने कहा—“राजकुमार, किले में रहकर अंतिम साँस तक लड़ेंगे।”

उदय सिंह ने गंभीर स्वर में उत्तर दिया—“यदि हम सब यहीं समाप्त हो गए, तो मेवाड़ की ज्योति कौन जलाएगा? युद्ध केवल आज का नहीं, आने वाली पीढ़ियों का है।”

यह निर्णय सरल नहीं था। पर उसने पहाड़ियों की ओर हटकर गुरिल्ला नीति अपनाने का मार्ग चुना। चित्तौड़ में वीरों ने प्राण दिए, पर उदय सिंह ने संघर्ष को जीवित रखा। अरावली की घाटियाँ उसकी नई रणभूमि बनीं।

दूसरा बड़ा संघर्ष पहाड़ी दर्रे में हुआ। मुग़ल सेना भारी संख्या में आगे बढ़ रही थी। संकरा मार्ग, दोनों ओर ऊँची चट्टानें। उदय सिंह ने सैनिकों को ऊपर तैनात किया। आदेश स्पष्ट था—सीधा टकराव नहीं, पहले शत्रु को भीतर आने दो।

जैसे ही अग्रिम पंक्ति दर्रे में घुसी, ऊपर से पत्थर और बाण बरसने लगे। तोपें संकरे मार्ग में बेकार हो गईं। नीचे से मेवाड़ी घुड़सवारों ने आक्रमण किया। “एकलिंग जी की जय!” की गर्जना गूँजी। मुग़ल सेना में भ्रम फैल गया। यह रणनीतिक विजय थी—संख्या पर भूगोल की जीत।

उदय सिंह केवल तलवार नहीं चलाता था, वह भविष्य गढ़ रहा था। उसने झीलों और पहाड़ियों के बीच एक नए नगर की कल्पना की—एक ऐसा स्थान जहाँ से संघर्ष जारी रखा जा सके। इस प्रकार उदयपुर की नींव पड़ी—रणनीतिक दृष्टि का प्रतीक।

पर युद्ध थमे नहीं। एक और संघर्ष मैदान में हुआ। इस बार मुग़ल सेना ने खुली चुनौती दी। दोनों ओर पंक्तियाँ सजीं। तोपों की गर्जना, नगाड़ों की ध्वनि, धूल का गुबार।

उदय सिंह अग्रिम पंक्ति में था। उसकी तलवार सूर्य की किरणों में चमक रही थी। “मेवाड़!” उसकी आवाज़ में ऐसी शक्ति थी कि सैनिकों की थकान मिट गई।

युद्ध भयंकर था। भाले ढालों में धँसे, तलवारें कवच चीरती रहीं। एक क्षण ऐसा आया जब शत्रु ने उसे घेर लिया। चारों ओर से वार। उसने ढाल घुमाई, एक प्रहार रोका, दूसरे का उत्तर दिया। उसके कंधे पर घाव हुआ, पर वह पीछे नहीं हटा।

“राजकुमार, पीछे हटिए!” एक सरदार चिल्लाया।

उदय सिंह ने उत्तर दिया—“जब तक यह तलवार उठी है, मेवाड़ जीवित है!”

घंटों के संघर्ष के बाद शत्रु पीछे हटा। मैदान रक्त से भीग चुका था, पर ध्वज अब भी फहरा रहा था।

समय बीतता गया। घाव गहराते गए। पर उसकी आँखों में दृढ़ता कम न हुई। उसने अपने पुत्र प्रताप को शस्त्र सिखाए, उसे बताया—“स्वतंत्रता का मूल्य प्राणों से चुकाना पड़ता है।”

अंतिम दिनों में भी वह आत्मसमर्पण के विचार से दूर रहा। उसने स्पष्ट कहा—“सिसोदिया झुकते नहीं।” उसका शरीर थका था, पर आत्मा अडिग।

जब उसका अंतिम क्षण आया, अरावली पर सूर्य अस्त हो रहा था। लालिमा फैल रही थी—मानो आकाश भी उस योद्धा को सलाम कर रहा हो। उसने अंतिम बार मेवाड़ की दिशा में दृष्टि डाली। उसके होंठों पर एक शब्द था—“स्वतंत्रता।”

उसकी साँस थम गई, पर संघर्ष नहीं। उसकी विरासत प्रताप के रूप में आगे बढ़ी। अरावली की चोटियाँ आज भी उस नाम को याद करती हैं—उदय सिंह। वह केवल एक राजकुमार नहीं था; वह वह दीवार था जिसने तूफ़ान को रोके रखा, ताकि अगली पीढ़ी तलवार उठा सके।

और जब भी मेवाड़ की हवाएँ चलती हैं, उनमें एक स्वर गूँजता है—
“सिसोदिया अमर हैं।” `
